-- 00_account/05_service_user.sql
-- TYPE=SERVICE user for GitHub Actions. Key-pair (JWT) auth only, no password.
-- The matching private key (keys/rsa_key.p8) is stored as the GitHub secret
-- SNOWFLAKE_PRIVATE_KEY. Rotate by replacing both this key and the secret.

USE ROLE ACCOUNTADMIN;

CREATE USER IF NOT EXISTS SVC_GH_ACTIONS_AIRLINE
  TYPE = SERVICE
  DEFAULT_ROLE = PROD_GH_ACTIONS_DEPLOY_RL
  DEFAULT_WAREHOUSE = AIRLINE_DEMO_WH
  RSA_PUBLIC_KEY = ''
  COMMENT = 'Service account for GitHub Actions deployments to AIRLINE_PROD';

GRANT ROLE PROD_GH_ACTIONS_DEPLOY_RL TO USER SVC_GH_ACTIONS_AIRLINE;
